static bool is_word(const char *text, size_t length)
{
    if (length < 1 || length > MAX_WORD_LENGTH) {
        return false;
    }
    for (size_t index = 0; index < length; index++) {
        if (!isalpha((unsigned char)text[index])) {
            return false;
        }
